# -*- coding: utf-8 -*-
S = "сплошной скан: в пределах и функциях $\\sin\\frac{x}{x}$ вместо $\\frac{\\sin x}{x}$; проверено по ключам (замечательный предел равен 1)"
P = {}
def E(t, why, **kw): P[t] = dict(src=S, why=why, **kw)
E('G11_TB_§2_2_12_а', "в условии дробь $\\frac{\\sin u}{u}$ была записана как $\\sin\\frac{u}{u}$ (тождественно $\\sin 1$); ключ относится к $\\frac{\\sin u}{u}$", q='Вычислите: $$\\lim_{x\\to0} \\dfrac{\\sin 2x}{2x}$$')
E('G11_TB_§2_2_12_в', "в условии дробь $\\frac{\\sin u}{u}$ была записана как $\\sin\\frac{u}{u}$ (тождественно $\\sin 1$); ключ относится к $\\frac{\\sin u}{u}$", q='Вычислите: $$\\lim_{x\\to0} \\dfrac{\\sin \\pi x}{\\pi x}$$')
E('G11_TB_3_1_2_40_2', "в условии дробь $\\frac{\\sin u}{u}$ была записана как $\\sin\\frac{u}{u}$ (тождественно $\\sin 1$); ключ относится к $\\frac{\\sin u}{u}$", q='Имеет ли точки разрыва функция: $y = \\dfrac{\\sin x}{x}$, если $x \\neq 0$; $1$, если $x = 0$?')
E('G11_TB_§3_2_40_2', "в условии дробь $\\frac{\\sin u}{u}$ была записана как $\\sin\\frac{u}{u}$ (тождественно $\\sin 1$); ключ относится к $\\frac{\\sin u}{u}$", q='Имеет ли точки разрыва функция:\nб) $y = \\dfrac{\\sin x}{x}$, если $x \\neq 0$; $1$, если $x = 0$')
E('G11_TB_2_2_52_4', "в условии дробь $\\frac{\\sin u}{u}$ была записана как $\\sin\\frac{u}{u}$ (тождественно $\\sin 1$); ключ относится к $\\frac{\\sin u}{u}$", q='Функция $y=\\dfrac{\\sin x}{x}$ определена для всех значений $x$ за исключением $x=0$. Покажите, что $$\\lim_{x\\to0+}\\dfrac{\\sin x}{x}=1$$ и $$\\lim_{x\\to0-}\\dfrac{\\sin x}{x}=1$$, следовательно, эта функция при $x\\to0$ имеет предел, равный $1$. Этот предел называют первым замечательным пределом.')
